      final ckpts = (await session.getEntries())
          .whereType<CompactCheckpointRecord>()
          .toList();
      expect(ckpts, hasLength(1), reason: 'relief after one checkpoint: $ok');
      final ckpt = ckpts.single;
      expect(ckpt.text, contains('token-expiry'));
