provider: openai-completions
model: test-model
baseUrl: http://127.0.0.1:$port/v1
mode: code
approvalMode: yolo
allowedTools: [read]
# Pin the classic chrome: this suite asserts the pre-#805 classic status
# row; the band redesign (#805-#807) has its own surface.
tui:
